import unittest
class TestAbs(unittest.TestCase):
    def test_neg(self):
        out = run_student_code(inputs=['-7'])
        if "-7" in out and "7" not in out:
             self.fail("❌ Imprimiste -7. El valor absoluto debe ser positivo (7).")
        self.assertIn('7', out)

import unittest
class TestSoup(unittest.TestCase):
    def test_kramer(self):
        out = run_student_code(inputs=['Kramer', '2'])
        self.assertIn('11.8', out)
    def test_jerry(self):
        # Jerry no debe preguntar por porciones
        try:
            out = run_student_code(inputs=['Jerry'])
        except StopIteration:
             self.fail("❌ El programa pidió un input extra (porciones) a Jerry. Jerry no come sopa.")

        self.assertNotIn("cost", out)

